<script setup>defineProps({ meta:Object });defineEmits(['page'])</script><template><div v-if="meta" class="pagination"><span>{{ meta.total }} résultat(s) · page {{ meta.current_page }} / {{ meta.last_page }}</span><div class="actions"><button class="button secondary" :disabled="meta.current_page <= 1" @click="$emit('page', meta.current_page - 1)">Précédent</button><button class="button secondary" :disabled="meta.current_page >= meta.last_page" @click="$emit('page', meta.current_page + 1)">Suivant</button></div></div></template>